// آزمون اتصال منبع خارجی — بخش ۳۱ سند
// بررسی دسترسی بدون ساخت مجموعه‌داده؛ وضعیت و آخرین پیام اتصال به‌روزرسانی می‌شود

import { NextRequest } from 'next/server'
import { db } from '@/lib/db'
import { ok, fail, logAudit } from '@/lib/server'
import { requirePerm, errorResponse } from '@/lib/auth'
import { testConnection, toConnectionRecord } from '@/lib/connectors'

export async function POST(_req: NextRequest, ctx: { params: Promise<{ id: string }> }) {
  try {
    const user = await requirePerm(_req, 'dataset.create')
    const { id } = await ctx.params
    const row = await db.externalConnection.findUnique({ where: { id } })
    if (!row) return fail('اتصال یافت نشد.', 404)
    const result = await testConnection(toConnectionRecord(row))
    await logAudit(row.projectId, 'آزمون اتصال خارجی', `«${row.name}»: ${result.ok ? 'موفق' : 'ناموفق'} — ${result.message.slice(0, 80)}`, user.name)
    return ok({ result })
  } catch (e) {
    return errorResponse(e)
  }
}
